function maxCopies(tiles: string, word: string): number {
  const have = new Map<string, number>();
  for (const c of tiles) have.set(c, (have.get(c) ?? 0) + 1);
  let copies = 0;
  for (;;) {
    for (const c of word) {
      const left = have.get(c) ?? 0;
      if (left === 0) return copies;
      have.set(c, left - 1);
    }
    copies++;
  }
}

