function maxCopies(tiles: string, word: string): number {
  const have = new Array(26).fill(0), need = new Array(26).fill(0);
  for (const c of tiles) have[c.charCodeAt(0) - 97]++;
  for (const c of word) need[c.charCodeAt(0) - 97]++;
  let best = Infinity;
  for (let i = 0; i < 26; i++) {
    if (need[i] > 0) best = Math.min(best, Math.floor(have[i] / need[i]));
  }
  return best;
}

